  /* «Каркас» №4, 7а-1: согласие, документы, помощь и поддержка (docs/specs/19 §5) */
  "legal.terms.title": "Terms of Service",
  "legal.privacy.title": "Privacy Policy",
  "legal.agree.a11y": "I agree to the Terms of Service and the Privacy Policy",
  "legal.err.needed": "Accept the Terms of Service and the Privacy Policy first.",
  "legal.err.outdated": "The terms have changed. Update the app to see the new text.",
  "legal.err.network": "Check the connection and try again — then it will save.",
  "legal.gate.firstTitle": "Terms",
  "legal.gate.firstBody": "Before you continue, read and accept the Terms of Service and the Privacy Policy.",
  "legal.gate.changedTitle": "The terms have changed",
  "legal.gate.changedBody": "We updated the Terms of Service or the Privacy Policy. To keep working, read and accept the new edition.",
  "legal.gate.whatChanged": "What changed is listed at the top of each document.",
  "legal.gate.accept": "Accept",
  "legal.gate.signOut": "Sign out",
  "legal.edition": "Edition of {date}",
  "legal.draft": "Draft",
  "legal.englishGoverns": "This is a translation for convenience. The English text governs.",
  "legal.notFound": "No such document",
  "legal.terms.1.t": "Who agrees",
  "legal.terms.1.b": "These terms are between GoRix and the contracting company that uses it. The person who accepts them confirms they may act for that company.",
  "legal.terms.2.t": "What GoRix is",
  "legal.terms.2.b": "GoRix is a software tool. It is not a lawyer, an accountant, a tax adviser or a licensed contractor, and it is not a party to your contracts with your customers. Templates, calculations, taxes and hints are information only; you check and choose them.",
  "legal.terms.3.t": "Your responsibilities",
  "legal.terms.3.b": "You are responsible for your licenses and insurance, for your contracts, prices, taxes and deposits being lawful, for the consent of the people you message, and for the accuracy of your data.",
  "legal.terms.4.t": "Messages",
  "legal.terms.4.b": "You are the sender of texts and emails to your customers: you choose the recipient, the time and the words. GoRix may pause sending after complaints.",
  "legal.terms.5.t": "As is",
  "legal.terms.5.b": "GoRix is provided as is, without implied warranties and without a promise of uninterrupted work. Keep exports and backups of what matters to you.",
  "legal.terms.6.t": "Limits of liability",
  "legal.terms.6.b": "Our liability is limited to what you paid GoRix in the 12 months before a claim (on a free plan, $100), without indirect losses, except where the law does not allow such a limit.",
  "legal.terms.7.t": "Your data",
  "legal.terms.7.b": "Your data belongs to you. GoRix does not sell it, does not share it for advertising and does not use it to train models. After an account is closed you have 90 days to export it.",
  "legal.terms.8.t": "Changes",
  "legal.terms.8.b": "We show the new edition in the app before it takes effect. Material changes are accepted again the next time you sign in.",
  "legal.terms.basis": "Draft. The final text will be based on the Common Paper Cloud Service Agreement (CC BY 4.0).",
  "legal.privacy.1.t": "What we collect",
  "legal.privacy.1.b": "Your account (name, email, phone), your company profile, and what you enter about your customers, jobs, estimates, invoices and payments. Photos you attach. Technical data needed to run the service.",
  "legal.privacy.2.t": "Your customers' data",
  "legal.privacy.2.b": "We process your customers' data for you, as a service provider. We do not sell it and do not share it for marketing. Mobile information will not be shared with third parties or affiliates for marketing/promotional purposes.",
  "legal.privacy.sms.note": "The text SMS carriers require (A2P 10DLC registration):",
  "legal.privacy.sms.text": "Mobile information will not be shared with third parties or affiliates for marketing/promotional purposes.",
  "legal.privacy.3.t": "Who we share with",
  "legal.privacy.3.b": "Only the services that run GoRix: hosting and database, app builds and updates, email delivery, and payments when you turn them on. Each gets only what it needs.",
  "legal.privacy.4.t": "No tracking",
  "legal.privacy.4.b": "There are no ads and no third-party analytics or trackers. We do not track you across sites, so we do not respond to Do Not Track differently.",
  "legal.privacy.5.t": "Correct or delete",
  "legal.privacy.5.b": "You can correct your data in the app. To delete your account, write to support from Help and support; what is deleted and what the company keeps, we tell you before deleting.",
  "legal.privacy.6.t": "How long we keep data",
  "legal.privacy.6.b": "While your account is active, and after closing as long as the law requires for business records such as invoices and receipts; then it is deleted.",
  "legal.privacy.7.t": "Changes and contact",
  "legal.privacy.7.b": "We announce changes in the app with the date they take effect. Questions about your data: write to support from Help and support.",
  "legal.privacy.basis": "Draft. The structure follows the Basecamp policies (CC BY 4.0) and CalOPPA.",
  "invite.legal": "To join the team, accept the Terms of Service and the Privacy Policy.",
