  "ds.rows.tax": "Tax in the estimate",
  "ds.rows.taxHint": "A totals row «% · Off», the rate by hand up to four decimals (type «abc» — a hint under the row, leaving the field brings back the saved rate), «%» puts the rate of the last estimate at once (seen and editable); below — a tax-exempt client: read only, and why (DS §8.7а).",
  "ds.rows.taxSum": "tax amount",
  "ds.rows.photoTile": "“Add photo” tile",
  "ds.rows.photoTileHint": "Thumbnail-sized, a one-line “Photo” caption, icon and caption in one tone, hairline dashed frame (§8.6). Large system font: the tile grows, the icon is not squeezed.",
  "ds.rows.live": "Live list drag",
  "ds.rows.liveHint": "Take «≡» (a mouse: the row; a finger: a hold): the row lifts, the neighbours make room, a bar shows the place. Haptics: lift, each new place, drop; let go where it was — none.",
