  "ds.rows.soon": "⬜ The sample comes with its component (the estimate editor).",
  "ds.rows.row": "Estimate row",
  "ds.rows.rowHint": "“Brief / Detailed”, the trash always shown; a tap opens it in place, one open; open — “˄ Collapse”, one row “Qty · Unit · Price”, “Kind” as a list, “Total · profit · %”. Hidden — a dashed frame, “Hidden from client” and “cost” (only when costs are visible). No profit on a folded row (§8.3).",
  "ds.rows.lineA": "Fence painting",
  "ds.rows.lineADesc": "Both sides, primer and one coat",
  "ds.rows.lineB": "Debris haul-away",
  "ds.rows.swipe": "Row swipe",
  "ds.rows.swipeHint": "Left — «Replace», «Delete» (no confirmation, «Undo»); right — «Hide». No full swipe, no vibration (Б13).",
  "ds.rows.swipeWeb": "The web has no swipe: the same actions are in «⋯» of the estimate row. On a phone: left — «Replace», «Delete»; right — «Hide» (Б13).",
  "ds.rows.swipeRow": "Estimate row",
  "ds.rows.fill": "“Fill” selection",
  "ds.rows.fillHint": "The chosen one is a raised neutral fill with a small shadow, ink 600 text; not yellow and not a status colour. Selection rows also get a check (DS “Selection”, #1306).",
