  "ds.rows.variants": "Good / Better / Best variants",
  "ds.rows.variantsHint": "Variant segments with the total under each, “★ recommended”, “Variant — copy”, a five-step “?” (§8.10).",
  "ds.rows.firstHint": "First-estimate hints",
