  "ds.rows.notes": "Notes and Terms",
  "ds.rows.notesHint": "Two estimate rows, each opens a sheet; a new estimate gets the company Terms in the client’s language (shown beside them), Notes start empty; arbitration — a warning (§8.12, #1304). “×” and a swipe save, like “Done”.",
  "ds.rows.fromTemplate": "From template…",
